  font-weight: 600;
}
.ds-capture-copy > span{
  font-size: 12px;
  line-height: 1.5;
  color: var(--muted,#696573);
}
.ds-timer{
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: var(--muted,#696573);
  margin-left: auto;
}
.ds-mic.ds-recording{
  background: #a23b58;
}
.ds-capture-bar:has(.ds-recording){
